mutation RepositoryCreate($input: CreateRepositoryInput!) {
	createRepository(input: $input) {
		repository {
			id
			name
			owner { login }
			url
		}
	}
}

query RepositoryInfo($owner: String!, $name: String!) {
		repository(owner: $owner, name: $name) {isPrivate,description}
	}
